/**
 * Idempotent upserts for Sources + Highlights.
 *
 * IDs are UUIDs generated by the extension and travel with the payload. The
 * same ID arriving twice (e.g. duplicate sync) overwrites the same row.
 */

function upsertSource_(studentSheet, source) {
  validateSourcePayload_(source);
  const tab = getTab_(studentSheet, TABS.SOURCES);
  ensureHeaders_(tab, HEADERS.SOURCES);
  const row = {
    sourceId: source.sourceId,
    projectId: source.projectId,
    normalizedUrl: source.normalizedUrl || normalizeUrl_(source.rawUrl),
    rawUrl: source.rawUrl,
    accessDate: source.accessDate || nowIso_(),
    scrapedTitle: source.scrapedTitle || '',
    scrapedSite: source.scrapedSite || '',
    scrapedDate: source.scrapedDate || '',
    scrapedAuthor: source.scrapedAuthor || '',
    sourceType: source.sourceType || '',
    citationFields: source.citationFields ? JSON.stringify(source.citationFields) : '',
    primarySecondary: source.primarySecondary || 'unset',
    annotation: source.annotation || '',
    annotationLastEdited: source.annotationLastEdited || '',
    createdByEmail: source.createdByEmail,
    createdAt: source.createdAt || nowIso_(),
  };
  upsertByKey_(tab, HEADERS.SOURCES, 'sourceId', row);
}

function upsertHighlight_(studentSheet, highlight) {
  validateHighlightPayload_(highlight);
  const tab = getTab_(studentSheet, TABS.HIGHLIGHTS);
  ensureHeaders_(tab, HEADERS.HIGHLIGHTS);
  const row = {
    highlightId: highlight.highlightId,
    sourceId: highlight.sourceId,
    projectId: highlight.projectId,
    primaryCategory: highlight.primaryCategory,
    secondaryCategory: highlight.secondaryCategory || '',
    highlightedText: highlight.highlightedText,
    note: highlight.note || '',
    createdByEmail: highlight.createdByEmail,
    createdAt: highlight.createdAt || nowIso_(),
  };
  upsertByKey_(tab, HEADERS.HIGHLIGHTS, 'highlightId', row);
}

function validateSourcePayload_(s) {
  if (!s.sourceId) throw new Error('source.sourceId required');
  if (!s.projectId) throw new Error('source.projectId required');
  if (!s.rawUrl) throw new Error('source.rawUrl required');
  if (!s.createdByEmail) throw new Error('source.createdByEmail required');
  if (s.primarySecondary && PRIMARY_SECONDARY.indexOf(s.primarySecondary) < 0) {
    throw new Error(`source.primarySecondary must be one of ${PRIMARY_SECONDARY.join(', ')}`);
  }
  if (s.sourceType && SOURCE_TYPES.indexOf(s.sourceType) < 0) {
    throw new Error(`source.sourceType must be one of ${SOURCE_TYPES.join(', ')}`);
  }
}

function validateHighlightPayload_(h) {
  if (!h.highlightId) throw new Error('highlight.highlightId required');
  if (!h.sourceId) throw new Error('highlight.sourceId required');
  if (!h.projectId) throw new Error('highlight.projectId required');
  // primaryCategory is optional — students can save a note-only highlight
  // and categorize later in the sidebar. (Build plan §2 originally required
  // it at capture time, but Paul relaxed this 2026-05-26 so the act of
  // saving a useful note doesn't block on choosing a category.)
  if (!h.highlightedText) throw new Error('highlight.highlightedText required');
  if (!h.createdByEmail) throw new Error('highlight.createdByEmail required');
}
